# Generated by scripts/homebrew-formulas.py in tinhthanh/shipyard for v0.3.31-fork.6.
class Vetgo < Formula
  desc "Run coding agents on your own boxes: the berth CLI and laptop agent"
  homepage "https://github.com/tinhthanh/shipyard"
  version "0.3.31-fork.6"
  license "MIT"

  on_macos do
    on_arm do
      url "https://github.com/tinhthanh/shipyard/releases/download/v0.3.31-fork.6/berth-darwin-arm64.tar.gz"
      sha256 "3f27cfe0c0f08979dc46d2c37b4eb6d33ef35347dfee382392b0399cb50cbeda"
    end
    on_intel do
      url "https://github.com/tinhthanh/shipyard/releases/download/v0.3.31-fork.6/berth-darwin-amd64.tar.gz"
      sha256 "7e47ce5cd1b722eee1954c92203db9aa81060b6708c5bc63f6f6b3e35ab3f999"
    end

    # The berthd builds `berth upgrade` puts on Mac boxes; the Linux ones
    # come in berth's own archive.
    resource "berthd-darwin-arm64" do
      url "https://github.com/tinhthanh/shipyard/releases/download/v0.3.31-fork.6/berthd-darwin-arm64.tar.gz"
      sha256 "68c573389aa984e18190b8f4482a26f08545467d6ce41b8f1fd594c7f88ed2a5"
    end
    resource "berthd-darwin-amd64" do
      url "https://github.com/tinhthanh/shipyard/releases/download/v0.3.31-fork.6/berthd-darwin-amd64.tar.gz"
      sha256 "5d569abd2a371eb9b93abf1913eae1b7f389cd5f8a09d8ed5c24d855e6be13b5"
    end
  end
  on_linux do
    on_arm do
      url "https://github.com/tinhthanh/shipyard/releases/download/v0.3.31-fork.6/berth-linux-arm64.tar.gz"
      sha256 "568108c66ddab9d1654b29885aba73536f1a468238f90813ad4904f04caf7b5c"
    end
    on_intel do
      url "https://github.com/tinhthanh/shipyard/releases/download/v0.3.31-fork.6/berth-linux-amd64.tar.gz"
      sha256 "0fa92b86ed31703e07a9c81709368bd7261ff08c06d97a37d350e3981d1121da"
    end
  end

  def install
    # berth looks beside its own file (through the link in bin) for the
    # berthd and tmux builds it uploads to boxes.
    libexec.install Dir["*"]
    if OS.mac?
      %w[arm64 amd64].each do |arch|
        resource("berthd-darwin-#{arch}").stage { libexec.install "berthd" => "berthd-darwin-#{arch}" }
      end
    end
    bin.install_symlink libexec/"berth"
  end

  def caveats
    <<~EOS
      Start the laptop agent, and have it start when you log in:
        berth agent install
      Add a box: berth add ssh USER@HOST (see berth help).
    EOS
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/berth version")
  end
end
